import os
import requests

def register_user(payload, config=None):
    config = config or {}
    url = "https://api.cognito.identity.aws.amazon.com"
    headers = {
        "X-Amz-Target": "AWSCognitoIdentityService.SignUp",
        "Content-Type": "application/x-amz-json-1.1"
    }
    client_id = config.get('client_id', os.getenv('COGNITO_CLIENT_ID'))
    user_pool_id = config.get('user_pool_id', os.getenv('COGNITO_USER_POOL_ID'))
    payload.update({
        "ClientId": client_id,
        "Username": payload['email'],
        "Password": payload['password'],
        "UserPoolId": user_pool_id
    })
    response = requests.post(url, headers=headers, json=payload)
    result = response.json()
    return result
